INSERT INTO leave_types (code, description, paid, notes) VALUES ('W', 'Worked', '-', 'Not a leave type - normal working day');
INSERT INTO leave_types (code, description, paid, notes) VALUES ('OFF', 'Rest Day (Saturday)', '-', 'Scheduled non-working day');
INSERT INTO leave_types (code, description, paid, notes) VALUES ('REST', 'Rest Day (Sunday)', '-', 'Scheduled non-working day');
INSERT INTO leave_types (code, description, paid, notes) VALUES ('PH', 'Public Holiday', 'Yes', 'From the Public Holidays tab');
INSERT INTO leave_types (code, description, paid, notes) VALUES ('AL', 'Annual Leave', 'Yes', 'Entitlement per employee on Employee Master');
INSERT INTO leave_types (code, description, paid, notes) VALUES ('MC', 'Medical (Sick) Leave', 'Yes', 'Supported by a medical certificate');
INSERT INTO leave_types (code, description, paid, notes) VALUES ('HL', 'Hospitalisation Leave', 'Yes', 'Separate from MC per Employment Act 1955');
INSERT INTO leave_types (code, description, paid, notes) VALUES ('UL', 'Unpaid Leave', 'No', 'Reduces Gross Pay in Payroll');
INSERT INTO leave_types (code, description, paid, notes) VALUES ('PL', 'Maternity / Paternity Leave', 'Yes', 'Add exact entitlement/rules as needed');
INSERT INTO leave_types (code, description, paid, notes) VALUES ('EL', 'Emergency Leave', 'Yes', 'Company policy - adjust Paid? if unpaid at your company');
INSERT INTO leave_types (code, description, paid, notes) VALUES ('A', 'Absent (unauthorised)', 'No', 'Reduces Gross Pay in Payroll');
